package com.aurafarming;

import java.util.concurrent.TimeUnit;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class AuraTimingClockTest
{
	@Test
	public void firstCallAfterConstructionReturnsZero()
	{
		FakeNanoClock fake = new FakeNanoClock(1_000_000_000L);
		AuraTimingClock clock = new AuraTimingClock(fake);

		assertEquals(0L, clock.elapsedNanosAndReset());
	}

	@Test
	public void normalTickDeltaIsReturnedExactly()
	{
		FakeNanoClock fake = new FakeNanoClock(0L);
		AuraTimingClock clock = new AuraTimingClock(fake);
		clock.reset();

		long tickNanos = TimeUnit.MILLISECONDS.toNanos(600); // a typical game tick
		fake.advance(tickNanos);

		assertEquals(tickNanos, clock.elapsedNanosAndReset());
	}

	@Test
	public void deltaAboveCapIsCappedNotDiscarded()
	{
		FakeNanoClock fake = new FakeNanoClock(0L);
		AuraTimingClock clock = new AuraTimingClock(fake);
		clock.reset();

		// A moderate lag spike: more than the cap, but well under the freeze threshold.
		fake.advance(TimeUnit.MILLISECONDS.toNanos(5000));

		assertEquals(AuraTimingClock.MAX_DELTA_NANOS, clock.elapsedNanosAndReset());
	}

	@Test
	public void deltaAboveFreezeThresholdIsDiscardedEntirely()
	{
		FakeNanoClock fake = new FakeNanoClock(0L);
		AuraTimingClock clock = new AuraTimingClock(fake);
		clock.reset();

		fake.advance(TimeUnit.SECONDS.toNanos(120)); // simulated freeze / long minimize

		assertEquals(0L, clock.elapsedNanosAndReset());
	}

	@Test
	public void consecutiveCallsDoNotDoubleCount()
	{
		FakeNanoClock fake = new FakeNanoClock(0L);
		AuraTimingClock clock = new AuraTimingClock(fake);
		clock.reset();

		long tick = TimeUnit.MILLISECONDS.toNanos(600);
		fake.advance(tick);
		long first = clock.elapsedNanosAndReset();

		fake.advance(tick);
		long second = clock.elapsedNanosAndReset();

		assertEquals(tick, first);
		assertEquals(tick, second);
		// Total across both calls equals exactly the total time advanced — nothing was
		// counted twice, and nothing was lost.
		assertEquals(2 * tick, first + second);
	}

	@Test
	public void clockGoingBackwardsNeverProducesNegativeDuration()
	{
		FakeNanoClock fake = new FakeNanoClock(1_000_000_000L);
		AuraTimingClock clock = new AuraTimingClock(fake);
		clock.reset();

		fake.set(500_000_000L); // clock moved backwards, which should never happen but must be defended against

		assertEquals(0L, clock.elapsedNanosAndReset());
	}

	/**
	 * Simple controllable fake implementing the package-private {@code NanoClock} seam.
	 */
	private static final class FakeNanoClock implements AuraTimingClock.NanoClock
	{
		private long currentNanos;

		private FakeNanoClock(long startNanos)
		{
			this.currentNanos = startNanos;
		}

		private void advance(long nanos)
		{
			this.currentNanos += nanos;
		}

		private void set(long nanos)
		{
			this.currentNanos = nanos;
		}

		@Override
		public long nanoTime()
		{
			return currentNanos;
		}
	}
}

package com.aurafarming;

import com.google.gson.Gson;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;

public class LocalAuraRepositoryTest
{
	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	private final Gson gson = new Gson();
	private static final long ACCOUNT_A = 111111L;
	private static final long ACCOUNT_B = 222222L;

	private LocalAuraRepository newRepository()
	{
		return new LocalAuraRepository(gson, temporaryFolder.getRoot());
	}

	@Test
	public void loadingWhenNoFileExistsReturnsFreshSession()
	{
		LocalAuraRepository repository = newRepository();

		AuraSession session = repository.load(ACCOUNT_A);

		assertNotNull(session);
		assertEquals(0L, session.getEligibleAuraDurationSeconds());
	}

	@Test
	public void saveThenLoadRoundTripsCorrectly()
	{
		LocalAuraRepository repository = newRepository();

		AuraSession original = new AuraSession();
		original.addEligibleSeconds(12345);
		repository.save(ACCOUNT_A, original);

		AuraSession loaded = repository.load(ACCOUNT_A);

		assertEquals(12345L, loaded.getEligibleAuraDurationSeconds());
		assertEquals(12345L, loaded.getCurrentSessionEligibleSeconds());
	}

	@Test
	public void twoAccountsNeverShareProgress()
	{
		// The actual bug this whole scoping exists to fix: logging into a second
		// RuneScape account on the same machine must not inherit the first account's
		// accumulated time.
		LocalAuraRepository repository = newRepository();

		AuraSession accountASession = new AuraSession();
		accountASession.addEligibleSeconds(500);
		repository.save(ACCOUNT_A, accountASession);

		AuraSession accountBSession = repository.load(ACCOUNT_B);

		assertEquals(0L, accountBSession.getEligibleAuraDurationSeconds());
	}

	@Test
	public void aDeviceIdIsIndependentPerAccount()
	{
		LocalAuraRepository repository = newRepository();

		AuraSession accountASession = repository.load(ACCOUNT_A);
		String deviceIdA = accountASession.getOrCreateDeviceId();
		repository.save(ACCOUNT_A, accountASession);

		AuraSession accountBSession = repository.load(ACCOUNT_B);
		String deviceIdB = accountBSession.getOrCreateDeviceId();
		repository.save(ACCOUNT_B, accountBSession);

		assertNotEquals(deviceIdA, deviceIdB);
	}

	@Test
	public void sameAccountKeepsItsProgressAcrossReloads()
	{
		// Simulates a rename: the account (accountHash) is the same even though the
		// character's display name would have changed — nothing about this repository
		// depends on display name, so progress survives.
		LocalAuraRepository repository = newRepository();

		AuraSession session = repository.load(ACCOUNT_A);
		session.addEligibleSeconds(9000);
		repository.save(ACCOUNT_A, session);

		AuraSession reloaded = repository.load(ACCOUNT_A);

		assertEquals(9000L, reloaded.getEligibleAuraDurationSeconds());
	}

	@Test
	public void corruptFileReturnsFreshSessionInsteadOfThrowing() throws IOException
	{
		File sessionsDir = temporaryFolder.getRoot();
		try (FileWriter writer = new FileWriter(new File(sessionsDir, ACCOUNT_A + ".json")))
		{
			writer.write("{ this is not valid json ][");
		}

		LocalAuraRepository repository = newRepository();
		AuraSession session = repository.load(ACCOUNT_A);

		assertNotNull(session);
		assertEquals(0L, session.getEligibleAuraDurationSeconds());
	}

	@Test
	public void negativeDurationInFileIsSanitizedToFreshSession() throws IOException
	{
		File sessionsDir = temporaryFolder.getRoot();
		try (FileWriter writer = new FileWriter(new File(sessionsDir, ACCOUNT_A + ".json")))
		{
			writer.write("{\"schemaVersion\":1,\"eligibleAuraDurationSeconds\":-500,"
				+ "\"currentSessionEligibleSeconds\":0,\"lastSavedAtEpochMillis\":0}");
		}

		LocalAuraRepository repository = newRepository();
		AuraSession session = repository.load(ACCOUNT_A);

		assertEquals(0L, session.getEligibleAuraDurationSeconds());
	}

	@Test
	public void implausiblyLargeDurationInFileIsSanitizedToFreshSession() throws IOException
	{
		// Data hygiene, not anti-cheat — see LocalAuraRepository's MAX_PLAUSIBLE_ELIGIBLE_SECONDS
		// javadoc for why a moderately-sized fabricated edit is NOT caught by this and
		// isn't meant to be; the real protection is server-side.
		File sessionsDir = temporaryFolder.getRoot();
		try (FileWriter writer = new FileWriter(new File(sessionsDir, ACCOUNT_A + ".json")))
		{
			writer.write("{\"schemaVersion\":1,\"eligibleAuraDurationSeconds\":999999999999,"
				+ "\"currentSessionEligibleSeconds\":0,\"lastSavedAtEpochMillis\":0}");
		}

		LocalAuraRepository repository = newRepository();
		AuraSession session = repository.load(ACCOUNT_A);

		assertEquals(0L, session.getEligibleAuraDurationSeconds());
	}
}

package com.aurafarming;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Covers only {@link AuraPlugin#shouldShowZeroAuraNotice}, the pure decision logic
 * pulled out of {@code maybeShowZeroAuraNotice} specifically so it doesn't need a
 * mocked {@code Client}/{@code ConfigManager}/{@code ClientThread} — see that
 * method's own doc comment. The "already shown this session" and the actual chat
 * message / config write are deliberately untested here: they're the same kind of
 * RuneLite-glue code the rest of {@link AuraPlugin} already has no direct test
 * coverage for.
 */
public class AuraPluginZeroAuraNoticeTest
{
	private static final int THRESHOLD = 5;

	@Test
	public void staysHiddenBelowTheThresholdOnAFreshInstall()
	{
		assertFalse(AuraPlugin.shouldShowZeroAuraNotice(false, 0, THRESHOLD));
		assertFalse(AuraPlugin.shouldShowZeroAuraNotice(false, THRESHOLD - 1, THRESHOLD));
	}

	@Test
	public void showsOnceTheStreakReachesTheThreshold()
	{
		assertTrue(AuraPlugin.shouldShowZeroAuraNotice(false, THRESHOLD, THRESHOLD));
		assertTrue(AuraPlugin.shouldShowZeroAuraNotice(false, THRESHOLD + 50, THRESHOLD));
	}

	@Test
	public void showsImmediatelyOnceTheThresholdWasAlreadyClearedInAnEarlierSession()
	{
		// A later session's streak resets to whatever this sync tick's local count is
		// (it's never reset in AuraSession, but a fresh session could still start
		// mid-streak at a low number) — the persisted "cleared" flag must be enough on
		// its own, independent of the current streak value.
		assertTrue(AuraPlugin.shouldShowZeroAuraNotice(true, 0, THRESHOLD));
		assertTrue(AuraPlugin.shouldShowZeroAuraNotice(true, 1, THRESHOLD));
	}
}

package com.aurafarming;

import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GrandExchangeAreaTest
{
	// A small, deterministic octagon independent of the production constants, so this
	// test does not silently pass/fail if the real GE bounds are later corrected. A
	// 20x20 square with each corner cut back by 4 tiles on the diagonal — the same
	// shape as the real courtyard, just at a size that's easy to reason about by hand.
	private static final int MIN_X = 100;
	private static final int MAX_X = 119;
	private static final int MIN_Y = 200;
	private static final int MAX_Y = 219;
	private static final int CORNER_CUT = 4;
	private static final int MIN_SUM = MIN_X + MIN_Y + CORNER_CUT;
	private static final int MAX_SUM = MAX_X + MAX_Y - CORNER_CUT;
	private static final int MIN_DIFF = MIN_X - MAX_Y + CORNER_CUT;
	private static final int MAX_DIFF = MAX_X - MIN_Y - CORNER_CUT;
	private static final int PLANE = 0;

	private GrandExchangeArea area;

	@Before
	public void setUp()
	{
		area = new GrandExchangeArea(MIN_X, MAX_X, MIN_Y, MAX_Y, MIN_SUM, MAX_SUM, MIN_DIFF, MAX_DIFF, PLANE);
	}

	@Test
	public void centerTileIsInside()
	{
		WorldPoint center = new WorldPoint((MIN_X + MAX_X) / 2, (MIN_Y + MAX_Y) / 2, PLANE);
		assertTrue(area.contains(center));
	}

	@Test
	public void midpointOfEachFlatEdgeIsInside()
	{
		int midX = (MIN_X + MAX_X) / 2;
		int midY = (MIN_Y + MAX_Y) / 2;

		// This is the exact regression a plain bounding-box check got wrong: real GE
		// tiles along the west/east walls, away from the corners, must count as inside.
		assertTrue(area.contains(new WorldPoint(MIN_X, midY, PLANE))); // west
		assertTrue(area.contains(new WorldPoint(MAX_X, midY, PLANE))); // east
		assertTrue(area.contains(new WorldPoint(midX, MAX_Y, PLANE))); // north
		assertTrue(area.contains(new WorldPoint(midX, MIN_Y, PLANE))); // south
	}

	@Test
	public void squareCornersAreOutsideTheOctagonCut()
	{
		// The four corners of the bounding square are exactly what the diagonal cut
		// removes — the whole reason this class stopped being a plain rectangle.
		assertFalse(area.contains(new WorldPoint(MIN_X, MIN_Y, PLANE))); // SW
		assertFalse(area.contains(new WorldPoint(MAX_X, MIN_Y, PLANE))); // SE
		assertFalse(area.contains(new WorldPoint(MIN_X, MAX_Y, PLANE))); // NW
		assertFalse(area.contains(new WorldPoint(MAX_X, MAX_Y, PLANE))); // NE
	}

	@Test
	public void tileImmediatelyOutsideWestEdgeIsOutside()
	{
		int midY = (MIN_Y + MAX_Y) / 2;
		WorldPoint outside = new WorldPoint(MIN_X - 1, midY, PLANE);
		assertFalse(area.contains(outside));
	}

	@Test
	public void tileImmediatelyOutsideEastEdgeIsOutside()
	{
		int midY = (MIN_Y + MAX_Y) / 2;
		WorldPoint outside = new WorldPoint(MAX_X + 1, midY, PLANE);
		assertFalse(area.contains(outside));
	}

	@Test
	public void sameXyDifferentPlaneIsOutside()
	{
		WorldPoint upstairs = new WorldPoint((MIN_X + MAX_X) / 2, (MIN_Y + MAX_Y) / 2, PLANE + 1);
		assertFalse(area.contains(upstairs));
	}

	@Test
	public void nullPointIsOutside()
	{
		assertFalse(area.contains(null));
	}
}

package com.aurafarming;

import com.google.gson.Gson;
import java.net.http.HttpClient;
import java.net.http.HttpHeaders;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Controlled HTTP completions and monotonic time: no sleeps or live API calls. */
public class AuraApiClientRecoveryTest
{
	private HttpClient transport;
	private AuraApiClient client;
	private AtomicLong clock;
	private CompletableFuture<HttpResponse<String>> pending;

	@Before
	public void setUp()
	{
		transport = mock(HttpClient.class);
		clock = new AtomicLong();
		pending = new CompletableFuture<>();
		when(transport.sendAsync(any(HttpRequest.class), org.mockito.ArgumentMatchers.<HttpResponse.BodyHandler<String>>any())).thenReturn(pending);
		client = new AuraApiClient(new Gson(), "http://local.test", transport, clock::get);
	}

	@SuppressWarnings("unchecked")
	private HttpResponse<String> response(int status, String retry, String body)
	{
		HttpResponse<String> response = mock(HttpResponse.class);
		when(response.statusCode()).thenReturn(status);
		when(response.body()).thenReturn(body);
		when(response.headers()).thenReturn(HttpHeaders.of(retry == null ? Collections.emptyMap() : Collections.singletonMap("Retry-After", List.of(retry)), (k, v) -> true));
		return response;
	}

	private void send(String device)
	{
		client.syncAsync(device, "Synthetic", 120, -1);
	}

	private void sent(int count)
	{
		verify(transport, times(count)).sendAsync(any(HttpRequest.class), org.mockito.ArgumentMatchers.<HttpResponse.BodyHandler<String>>any());
	}

	@Test
	public void rejectsOverlappingCallsButReleasesSlotAfterSuccess()
	{
		send("one");
		send("one");
		sent(1);
		pending.complete(response(200, null, "{\"accepted\":true}"));
		send("one");
		sent(2);
	}

	@Test
	public void respectsActual429AndResumesAtExpiry()
	{
		send("one");
		pending.complete(response(429, "120", "{}"));
		send("one");
		sent(1);
		clock.set(TimeUnit.SECONDS.toNanos(119));
		send("one");
		sent(1);
		clock.set(TimeUnit.SECONDS.toNanos(120));
		send("one");
		sent(2);
	}

	@Test
	public void blockedAccountDoesNotBlockAnotherAccount()
	{
		send("one");
		pending.complete(response(429, "120", "{}"));
		send("two");
		sent(2);
	}

	@Test
	public void connectionFailureReleasesSlot()
	{
		send("one");
		pending.completeExceptionally(new java.io.IOException("test connection failure"));
		send("one");
		sent(2);
	}

	@Test
	public void timeoutReleasesSlot()
	{
		send("one");
		pending.completeExceptionally(new java.net.http.HttpTimeoutException("test timeout"));
		send("one");
		sent(2);
	}

	@Test
	public void malformedSuccessDoesNotBlockFutureSyncs()
	{
		send("one");
		pending.complete(response(200, null, "<html>error</html>"));
		send("one");
		sent(2);
	}

	@Test
	public void businessRejectionDoesNotIntroduceACooldown()
	{
		send("one");
		pending.complete(response(200, null, "{\"accepted\":false,\"rejectionReason\":\"regression\"}"));
		assertTrue(client.canSync("one"));
		send("one");
		sent(2);
	}

	@Test
	public void synchronousTransportFailureDoesNotPermanentlyBlockDevice()
	{
		when(transport.sendAsync(any(HttpRequest.class), org.mockito.ArgumentMatchers.<HttpResponse.BodyHandler<String>>any())).thenThrow(new IllegalStateException("test closed transport"));
		send("one");
		send("one");
		sent(2);
	}

	@Test
	public void missingRetryHeaderFallsBackAndEventuallyExpires()
	{
		send("one");
		pending.complete(response(429, null, "{}"));
		clock.set(TimeUnit.SECONDS.toNanos(239));
		assertFalse(client.canSync("one"));
		clock.set(TimeUnit.SECONDS.toNanos(240));
		assertTrue(client.canSync("one"));
	}
}

package com.aurafarming;

import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class AuraSessionTrackerTest
{
	private static final int SW_X = 100;
	private static final int SW_Y = 200;
	private static final int PLANE = 0;

	private static final WorldPoint INSIDE_GE = new WorldPoint(SW_X + 2, SW_Y + 2, PLANE);
	private static final WorldPoint INSIDE_GE_DIFFERENT_TILE = new WorldPoint(SW_X + 3, SW_Y + 2, PLANE);
	private static final WorldPoint OUTSIDE_GE = new WorldPoint(SW_X - 50, SW_Y, PLANE);

	private static final int IDLE_DELAY_SECONDS = 5;

	private FakeClock fakeClock;
	private AuraSessionTracker tracker;
	private AuraSession session;

	@Before
	public void setUp()
	{
		GrandExchangeArea area = plainSquareArea();
		fakeClock = new FakeClock(0L);
		session = new AuraSession();
		tracker = new AuraSessionTracker(area, new AuraTimingClock(fakeClock), session, fakeClock);

		tracker.onGameStateChanged(GameState.LOGGED_IN);
	}

	@Test
	public void startsAsWaitingForIdleUponEnteringGe()
	{
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		assertEquals(AuraState.WAITING_FOR_IDLE, tracker.getState());
	}

	@Test
	public void doesNotStartEarningBeforeIdleDelayElapses()
	{
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		fakeClock.advanceSeconds(3);
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);

		assertEquals(AuraState.WAITING_FOR_IDLE, tracker.getState());
		assertEquals(0L, session.getCurrentSessionEligibleSeconds());
	}

	@Test
	public void startsEarningOnceIdleDelayElapses()
	{
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		fakeClock.advanceSeconds(IDLE_DELAY_SECONDS);
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);

		assertEquals(AuraState.EARNING_AURA, tracker.getState());
	}

	@Test
	public void movingToAnotherTileResetsIdleWait()
	{
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		fakeClock.advanceSeconds(IDLE_DELAY_SECONDS);
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		assertEquals(AuraState.EARNING_AURA, tracker.getState());

		tracker.onGameTick(INSIDE_GE_DIFFERENT_TILE, IDLE_DELAY_SECONDS);
		assertEquals(AuraState.WAITING_FOR_IDLE, tracker.getState());
	}

	@Test
	public void leavingGePausesTrackingButKeepsAccumulatedTotal()
	{
		enterGeAndStartEarning();
		accumulateOneRealisticTick(); // 1 whole second accumulated

		long accumulatedBeforeLeaving = session.getEligibleAuraDurationSeconds();
		assertEquals(1L, accumulatedBeforeLeaving);

		tracker.onGameTick(OUTSIDE_GE, IDLE_DELAY_SECONDS);

		assertEquals(AuraState.IN_GAME, tracker.getState());
		assertEquals(accumulatedBeforeLeaving, session.getEligibleAuraDurationSeconds());
	}

	@Test
	public void logoutStopsTrackingAndSubsequentTicksAreNoOps()
	{
		enterGeAndStartEarning();
		accumulateOneRealisticTick();
		long totalBeforeLogout = session.getEligibleAuraDurationSeconds();

		tracker.onGameStateChanged(GameState.LOGIN_SCREEN);
		assertEquals(AuraState.LOGGED_OUT, tracker.getState());

		// Even if somehow called again with a valid GE location, a logged-out tracker
		// must not accumulate anything.
		fakeClock.advanceSeconds(10);
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);

		assertEquals(AuraState.LOGGED_OUT, tracker.getState());
		assertEquals(totalBeforeLogout, session.getEligibleAuraDurationSeconds());
	}

	@Test
	public void worldHopDoesNotGrantFreeAuraAndRequiresFreshIdleWait()
	{
		enterGeAndStartEarning();

		tracker.onGameStateChanged(GameState.HOPPING);
		assertEquals(AuraState.PAUSED, tracker.getState());

		// Simulate a long hop delay — must never be counted as eligible time.
		fakeClock.advanceSeconds(20);

		tracker.onGameStateChanged(GameState.LOGGED_IN);
		assertEquals(AuraState.IN_GAME, tracker.getState());

		// Landing back on the same tile after a hop must NOT resume EARNING_AURA
		// directly — it must re-establish the idle wait from scratch.
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		assertEquals(AuraState.WAITING_FOR_IDLE, tracker.getState());
	}

	@Test
	public void noDoubleCountingOverManyRealisticTicks()
	{
		enterGeAndStartEarning();

		// 100 ticks of 600ms == exactly 60 seconds of real elapsed time.
		for (int i = 0; i < 100; i++)
		{
			fakeClock.advanceMillis(600);
			tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		}

		assertEquals(60L, session.getCurrentSessionEligibleSeconds());
		assertEquals(60L, session.getEligibleAuraDurationSeconds());
	}

	@Test
	public void loggedOutTrackerIgnoresGameTicksEntirely()
	{
		AuraSessionTracker freshTracker = new AuraSessionTracker(
			plainSquareArea(),
			new AuraTimingClock(fakeClock),
			new AuraSession(),
			fakeClock);

		freshTracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);

		assertEquals(AuraState.LOGGED_OUT, freshTracker.getState());
	}

	private void enterGeAndStartEarning()
	{
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		fakeClock.advanceSeconds(IDLE_DELAY_SECONDS);
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
		assertEquals(AuraState.EARNING_AURA, tracker.getState());
	}

	private void accumulateOneRealisticTick()
	{
		fakeClock.advanceMillis(1000);
		tracker.onGameTick(INSIDE_GE, IDLE_DELAY_SECONDS);
	}

	/**
	 * A plain 10x10 square, independent of the octagon-shaped production bounds — this
	 * test is about state-machine transitions, not the courtyard's real shape, so the
	 * diagonal bounds are left wide enough to never cut anything within the square.
	 */
	private static GrandExchangeArea plainSquareArea()
	{
		return new GrandExchangeArea(SW_X, SW_X + 9, SW_Y, SW_Y + 9, Integer.MIN_VALUE, Integer.MAX_VALUE,
			Integer.MIN_VALUE, Integer.MAX_VALUE, PLANE);
	}

	/**
	 * Controllable fake implementing both the {@link java.util.function.LongSupplier}
	 * seam used by {@link AuraSessionTracker} for idle-wait timestamps and the
	 * package-private {@link AuraTimingClock.NanoClock} seam used for earning deltas, so
	 * both can be driven from a single, deterministic time source in tests.
	 */
	private static final class FakeClock implements java.util.function.LongSupplier, AuraTimingClock.NanoClock
	{
		private long currentNanos;

		private FakeClock(long startNanos)
		{
			this.currentNanos = startNanos;
		}

		private void advanceSeconds(long seconds)
		{
			currentNanos += java.util.concurrent.TimeUnit.SECONDS.toNanos(seconds);
		}

		private void advanceMillis(long millis)
		{
			currentNanos += java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(millis);
		}

		@Override
		public long getAsLong()
		{
			return currentNanos;
		}

		@Override
		public long nanoTime()
		{
			return currentNanos;
		}
	}
}

package com.aurafarming;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class AuraSessionTest
{
	private AuraSession session;

	@Before
	public void setUp()
	{
		session = new AuraSession();
	}

	@Test
	public void zeroAuraSyncStreakStartsAtZero()
	{
		assertEquals(0, session.getZeroAuraSyncStreak());
	}

	@Test
	public void recordZeroAuraSyncIncrementsTheStreak()
	{
		session.recordZeroAuraSync();
		assertEquals(1, session.getZeroAuraSyncStreak());

		session.recordZeroAuraSync();
		session.recordZeroAuraSync();
		assertEquals(3, session.getZeroAuraSyncStreak());
	}

	@Test
	public void recordZeroAuraSyncKeepsCountingPastAnyRealisticThreshold()
	{
		for (int i = 0; i < 100; i++)
		{
			session.recordZeroAuraSync();
		}
		assertEquals(100, session.getZeroAuraSyncStreak());
	}

	@Test
	public void earningAuraDoesNotByItselfResetTheStreak()
	{
		// AuraPlugin only calls recordZeroAuraSync() while the total is still zero, so
		// in practice the streak simply stops being incremented once Aura is earned —
		// AuraSession itself has no reset logic, and none is needed (see the field's
		// own doc comment: once positive, the all-time total never returns to zero).
		session.recordZeroAuraSync();
		session.recordZeroAuraSync();
		session.addEligibleSeconds(60);

		assertEquals(2, session.getZeroAuraSyncStreak());
		assertEquals(60L, session.getEligibleAuraDurationSeconds());
	}
}

package com.aurafarming;

import com.google.gson.Gson;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Uses a real, ephemeral local HTTP server ({@link HttpServer}, built into the JDK) as a
 * test double for the backend — verifies the actual bytes {@link AuraApiClient} sends
 * over the wire, not just that some method was called.
 */
public class AuraApiClientTest
{
	private HttpServer server;
	private volatile String lastRequestBody;
	private volatile String lastRequestMethod;
	private volatile String lastContentType;
	private volatile String lastClientVersion;
	private CountDownLatch requestReceived;
	private int respondWithStatus = 200;

	@Before
	public void setUp() throws IOException
	{
		requestReceived = new CountDownLatch(1);
		server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/api/sync", this::handleSync);
		server.start();
	}

	@After
	public void tearDown()
	{
		server.stop(0);
	}

	private void handleSync(HttpExchange exchange) throws IOException
	{
		lastRequestMethod = exchange.getRequestMethod();
		lastContentType = exchange.getRequestHeaders().getFirst("Content-Type");
		lastClientVersion = exchange.getRequestHeaders().getFirst("X-Aura-Client-Version");
		lastRequestBody = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);

		byte[] response = "{\"accepted\":true,\"totalEligibleSeconds\":0,\"auraPoints\":0}".getBytes(StandardCharsets.UTF_8);
		exchange.sendResponseHeaders(respondWithStatus, response.length);
		try (OutputStream os = exchange.getResponseBody())
		{
			os.write(response);
		}
		requestReceived.countDown();
	}

	private String baseUrl()
	{
		return "http://127.0.0.1:" + server.getAddress().getPort();
	}

	private void awaitRequest() throws InterruptedException
	{
		if (!requestReceived.await(5, TimeUnit.SECONDS))
		{
			fail("Server never received a request within the timeout");
		}
	}

	@Test
	public void sendsExpectedRequestShape() throws InterruptedException, IOException
	{
		AuraApiClient client = new AuraApiClient(new Gson(), baseUrl());

		client.syncAsync("a1b2c3d4-e5f6-4789-a012-3456789abcde", "TestSlayer42", 752_400, 123456789L);
		awaitRequest();

		assertEquals("POST", lastRequestMethod);
		assertEquals("application/json", lastContentType);
		assertEquals(AuraApiClient.CLIENT_VERSION, lastClientVersion);
		java.util.Properties metadata = new java.util.Properties();
		try (java.io.InputStream stream = new java.io.FileInputStream("runelite-plugin.properties"))
		{
			metadata.load(stream);
		}
		assertEquals("Client version must match Plugin Hub metadata", metadata.getProperty("version"), lastClientVersion);
		assertTrue(lastRequestBody.contains("\"deviceId\":\"a1b2c3d4-e5f6-4789-a012-3456789abcde\""));
		assertTrue(lastRequestBody.contains("\"displayName\":\"TestSlayer42\""));
		assertTrue(lastRequestBody.contains("\"eligibleSecondsTotal\":752400"));
		// Sent as a string, not a bare JSON number — see syncAsync's own doc comment.
		assertTrue(lastRequestBody.contains("\"accountHash\":\"123456789\""));
	}

	@Test
	public void omitsAccountHashWhenNotResolvable() throws InterruptedException
	{
		AuraApiClient client = new AuraApiClient(new Gson(), baseUrl());

		client.syncAsync("a1b2c3d4-e5f6-4789-a012-3456789abcde", "TestSlayer42", 60, -1L);
		awaitRequest();

		assertTrue(lastRequestBody.contains("\"deviceId\""));
		assertFalse("accountHash key should be missing entirely, not null: was <" + lastRequestBody + ">",
			lastRequestBody.contains("\"accountHash\""));
	}

	@Test
	public void neverThrowsWhenServerIsUnreachable()
	{
		// Nothing is listening on this port (server from setUp() is a different one) —
		// simulates the backend being down. Must not throw: a sync failure can never
		// surface to the caller.
		AuraApiClient client = new AuraApiClient(new Gson(), "http://127.0.0.1:1");
		client.syncAsync("a1b2c3d4-e5f6-4789-a012-3456789abcde", "TestSlayer42", 60, -1L);
		// If we reach this line without an exception, the guarantee held.
	}

	@Test
	public void neverThrowsWhenServerReturnsAnErrorStatus() throws InterruptedException
	{
		respondWithStatus = 429;
		AuraApiClient client = new AuraApiClient(new Gson(), baseUrl());

		client.syncAsync("a1b2c3d4-e5f6-4789-a012-3456789abcde", "TestSlayer42", 60, -1L);
		awaitRequest();
		// No exception, no crash — the 429 is only ever logged (see AuraApiClient).
	}

	@Test
	public void distinguishesBusinessRejectionFromHttpSuccess()
	{
		AuraApiClient client = new AuraApiClient(new Gson(), baseUrl());
		AuraApiClient.SyncReply reply = client.parseSyncReply("{\"accepted\":false,\"rejectionReason\":\"regression\",\"totalEligibleSeconds\":1000}");
		assertFalse(reply.accepted);
		assertEquals("regression", reply.rejectionReason);
		assertEquals(1000, reply.totalEligibleSeconds);
		assertEquals(null, client.parseSyncReply("<html>error</html>"));
		assertEquals(null, client.parseSyncReply("{}"));
	}

	@Test
	public void cooldownIsScopedToTheRejectedDevice()
	{
		AuraApiClient client = new AuraApiClient(new Gson(), baseUrl());
		client.deferSync("device-one", "120");
		assertFalse(client.canSync("device-one"));
		assertTrue(client.canSync("device-two"));
		client.deferSync("device-two", "invalid");
		assertFalse(client.canSync("device-two"));
	}
}

package com.aurafarming;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class AuraScoreCalculatorTest
{
