import net.runelite.client.util.LinkBrowser;

/**
 * Aura Tracker — a purely cosmetic tracker for time spent standing still in the Grand
 * Exchange.
 * <p>
 * Local tracking (position reading, scoring, local persistence) is always on and never
 * touches the network — see {@link LocalAuraRepository}, {@link AuraSessionTracker}.
 * Online leaderboard sync ({@link AuraApiClient}) is the one part of this plugin that
 * does make network calls. It is opt-out: on by default, matching how RuneProfile (the
 * closest real precedent among existing RuneLite plugins that sync a client-calculated
 * value) behaves, rather than gated behind a confirmation dialog. The disclosure Plugin
 * Hub rule 1.3 requires is satisfied by {@link AuraConfig}'s config description plus a
 * one-time, non-blocking chat notice the first time a sync actually sends (see
 * {@link #doSyncOnline()}). No other player's data is ever read by any part of this
 * plugin.
 */
@Slf4j
@PluginDescriptor(
	name = "Aura Tracker",
	description = "Farm Aura by standing still at the Grand Exchange — brag about it on the optional community leaderboard.",
	tags = {"aura", "grand exchange", "idle", "tracker", "fun"}
)
public class AuraPlugin extends Plugin
{
	/**
	 * Safety-net interval only — logout is the primary sync trigger (see
	 * {@link #onGameStateChanged}), matching how the official OSRS Hiscores and the
	 * ecosystem's own WiseOldMan/XP Updater plugin work: they update on logout, not on a
	 * timer. A periodic fallback still exists for sessions long enough that waiting for
	 * logout would leave the leaderboard stale for hours.
	 */
	private static final int ONLINE_SYNC_INTERVAL_MINUTES = 15;

	/**
	 * Fixed, not user-configurable. Was previously an exposed config option; removed
	 * deliberately to keep the config panel to only the one setting that actually needs
	 * to be user-facing (online sync) — per the project's own "don't add settings unless
	 * genuinely useful" principle.
	 */
	private static final int IDLE_DELAY_SECONDS = 5;

	/**
	 * Hidden config key (no {@code @ConfigItem}, never shown in the settings panel) that
	 * tracks whether the one-time sync disclosure chat message has already been shown —
	 * see {@link #doSyncOnline()}. Deliberately never reset by toggling sync off and back
	 * on; once shown, it stays shown, so re-enabling never nags the user a second time.
	 */
	private static final String DISCLOSURE_SHOWN_KEY = "syncDisclosureShown";

	/**
	 * How many consecutive online syncs must report a zero all-time total before the
	 * "still 0 Aura" chat nudge is ever allowed to fire — see
	 * {@link #maybeShowZeroAuraNotice(AuraSession)}. At
	 * {@link #ONLINE_SYNC_INTERVAL_MINUTES}, 5 is well over an hour of continued play;
	 * deliberately not 1, so a brand-new install is never nagged on its very first
	 * sync, when everyone is still at zero. Only gates the *first* time ever — once a
	 * player has proven to be a genuine slow-progress case (not a fresh install), later
	 * sessions don't need to wait through this again; see
	 * {@link #zeroAuraNoticeShownThisSession}.
	 */
	private static final int ZERO_AURA_NOTICE_THRESHOLD = 5;

	/**
	 * Hidden config key (same pattern as {@link #DISCLOSURE_SHOWN_KEY}) recording that
	 * this account has cleared {@link #ZERO_AURA_NOTICE_THRESHOLD} at least once ever.
	 * Persisted forever and never cleared — its only job is to skip re-waiting through
	 * the threshold in later sessions, since a player who already proved they're a real
	 * slow-progress case (not a fresh install still warming up) doesn't need to prove
	 * it again. Session-to-session repetition itself is controlled separately by
	 * {@link #zeroAuraNoticeShownThisSession}, which is deliberately NOT persisted.
	 */
	private static final String ZERO_AURA_THRESHOLD_CLEARED_KEY = "zeroAuraThresholdCleared";

	/**
	 * The human-facing site (leaderboard, player pages) — a separate deployment from
	 * {@link AuraApiClient#baseUrlForDisplay()}, which is the API host data is actually
	 * sent to. Shown here specifically because {@code baseUrlForDisplay()} alone isn't
	 * something a player can actually go look at.
	 */
	private static final String LEADERBOARD_URL = "https://aura-web-one-green.vercel.app";
	private static final String DISCORD_URL = "https://discord.gg/55N6tCfUcm";

	@Inject
	private Client client;

	@Inject
	private AuraConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private LocalAuraRepository repository;

	@Inject
	private AuraApiClient apiClient;

	@Inject
	private Gson gson;

	private final GrandExchangeArea grandExchangeArea = new GrandExchangeArea();
	private final AuraScoreCalculator scoreCalculator = new AuraScoreCalculator();

	/**
	 * Deliberately a plain field, not a {@link #configManager} value — mirrors how the
	 * DropTracker RuneLite plugin's own {@code loginWarningsShown} field gates its
	 * once-per-login warnings (checked directly against that plugin's public source).
	 * A fresh {@code AuraPlugin} instance is created each time the plugin starts
	 * (client launch, or the plugin being re-enabled), so this naturally resets then —
	 * no explicit reset logic needed. Only meaningful once
	 * {@link #ZERO_AURA_THRESHOLD_CLEARED_KEY} is set; see
	 * {@link #maybeShowZeroAuraNotice(AuraSession)}.
	 */
	private boolean zeroAuraNoticeShownThisSession;

	private AuraSessionTracker tracker;
	private AuraPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> panelRefreshTask;
	private ScheduledFuture<?> autosaveTask;
	private ScheduledFuture<?> onlineSyncTask;

	/**
	 * The account {@link #tracker}'s current session was loaded for, or {@code -1} for
	 * "no real account seen yet" — the same sentinel {@link Client#getAccountHash()}
	 * itself uses for "not logged in", so the two compare correctly with no separate
	 * flag needed. Written only from the client thread (plugin lifecycle methods and
	 * {@code GameStateChanged} both run there); read from there and also, without ever
	 * calling {@code getAccountHash()} itself, by {@link #persist()} and
	 * {@link #doSyncOnline()} — both of which also run on the autosave/online-sync
	 * executor thread. {@code volatile} for that cross-thread visibility, same reason
	 * {@link #lastKnownDisplayName} already is.
	 */
	private volatile long loadedAccountHash = -1;

	/**
	 * Cached on the client thread every {@code GameTick} whenever the local player is
	 * resolvable (see {@link #onGameTick}), and read from other threads by
	 * {@link #syncOnline()}. This sidesteps two problems at once: {@code Client} methods
	 * like {@code getLocalPlayer()} are not safe to call from a background thread, and by
	 * the time a logout-triggered sync runs, {@code getLocalPlayer()} may already be null
	 * — the whole point of syncing on logout is to send the final state of a session that
	 * just ended, so it must not depend on reading the client fresh at that exact moment.
	 * {@code volatile} for cross-thread visibility without needing a lock for a single
	 * reference assignment.
	 */
	private volatile String lastKnownDisplayName;

	@Provides
	AuraConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AuraConfig.class);
	}

	@Override
	protected void startUp()
	{
		// Starts empty rather than loading a file here: which account's file to load
		// isn't known yet if the plugin starts before login (getAccountHash() is -1
		// until then). loadSessionForCurrentAccount() below fills in the real session
		// immediately if a player is already logged in (plugin enabled mid-session), or
		// leaves this in place until the next LOGIN — see onGameStateChanged.
		tracker = new AuraSessionTracker(grandExchangeArea, new AuraTimingClock(), new AuraSession());
		loadSessionForCurrentAccount();

		// The tracker always starts at LOGGED_OUT and otherwise only advances by reacting
		// to future GameStateChanged events. If the plugin is enabled while already
		// logged in (the common case — toggling a plugin on mid-session), no such event
		// will ever fire again, so the state machine would stay stuck at LOGGED_OUT
		// forever. Bootstrap it from the client's current state instead of assuming the
		// plugin always starts before login.
		tracker.onGameStateChanged(client.getGameState());

		panel = new AuraPanel(scoreCalculator, this::openLeaderboard, this::openDiscord, this::updateModelAsync);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "aura_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Aura Tracker")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		panelRefreshTask = executor.scheduleAtFixedRate(this::refreshPanel, 1, 1, TimeUnit.SECONDS);
		autosaveTask = executor.scheduleAtFixedRate(this::persist, 60, 60, TimeUnit.SECONDS);

		// On by default (see AuraConfig) — resumes/starts syncing on every plugin start
		// unless the user has turned it off.
		if (config.onlineSyncEnabled())
		{
			startOnlineSync();
		}
	}

	@Override
	protected void shutDown()
	{
		if (panelRefreshTask != null)
		{
			panelRefreshTask.cancel(true);
		}
		if (autosaveTask != null)
		{
			autosaveTask.cancel(true);
		}
		stopOnlineSync();

		persist();

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		// Belt-and-braces flush in case the client is closed without a clean plugin
		// shutDown() call (e.g. force-quit).
		persist();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (tracker == null)
		{
			return;
		}

		net.runelite.api.Player localPlayer = client.getLocalPlayer();
		net.runelite.api.coords.WorldPoint location = localPlayer != null ? localPlayer.getWorldLocation() : null;

		if (localPlayer != null)
		{
			String name = localPlayer.getName();
			if (name != null && !name.isEmpty())
			{
				lastKnownDisplayName = name;
			}
		}

		tracker.onGameTick(location, IDLE_DELAY_SECONDS);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (tracker == null)
		{
			return;
		}

		GameState newState = event.getGameState();
		tracker.onGameStateChanged(newState);

		if (newState == GameState.LOGGED_IN)
		{
			// A no-op unless the account actually changed (see the method's own doc) —
			// covers both "just logged in after plugin startup" and "switched to a
			// different account without restarting the client", the same way.
			loadSessionForCurrentAccount();
		}

		if (newState == GameState.LOGIN_SCREEN || newState == GameState.CONNECTION_LOST)
		{
			// Flush immediately on logout/disconnect rather than waiting for the next
			// autosave tick, so a quick logout never loses progress.
			persist();

			// Logout is the PRIMARY online sync trigger, not the periodic timer — matches
			// how the official OSRS Hiscores and WiseOldMan/XP Updater already behave in
			// this exact ecosystem (update on logout, not on a schedule). Only fires if
			// the user has actually opted in. Safe to call even though the local player
			// is no longer resolvable at this point — syncOnline() uses the cached
			// lastKnownDisplayName, not a fresh client read.
			if (config.onlineSyncEnabled())
			{
				syncOnline();
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"aurafarming".equals(event.getGroup()) || !"onlineSyncEnabled".equals(event.getKey()))
		{
			return;
		}

		if ("true".equals(event.getNewValue()))
		{
			startOnlineSync();
		}
		else
		{
			stopOnlineSync();
		}
	}

	private void startOnlineSync()
	{
		if (onlineSyncTask != null && !onlineSyncTask.isCancelled())
		{
			return;
		}

		onlineSyncTask = executor.scheduleAtFixedRate(
			this::syncOnline, 0, ONLINE_SYNC_INTERVAL_MINUTES, TimeUnit.MINUTES);
	}

	private void stopOnlineSync()
	{
		if (onlineSyncTask != null)
		{
			onlineSyncTask.cancel(false);
			onlineSyncTask = null;
		}
	}

	/**
	 * Called both by the periodic safety-net timer (background executor thread) and
	 * directly by {@link #onGameStateChanged} on logout (client thread) — must be safe
	 * from either. Never touches {@code Client} directly; uses {@link #lastKnownDisplayName}
	 * instead, which sidesteps both the thread-affinity requirement and the "player
	 * already logged out" problem.
	 * <p>
	 * Wrapped in try/catch as defense in depth: a {@code ScheduledExecutorService}
	 * silently and permanently stops running a periodic task the moment it throws an
	 * uncaught exception, with no log and no way to notice short of the sync simply never
	 * happening again — a failure mode this method must never be able to trigger,
	 * whatever future change might otherwise introduce one.
	 */
	private void syncOnline()
	{
		try
		{
			doSyncOnline();
		}
		catch (RuntimeException e)
		{
			log.warn("Aura Tracker: online sync tick failed unexpectedly", e);
		}
	}

	private void doSyncOnline()
	{
		if (tracker == null)
		{
			return;
		}

		String displayName = lastKnownDisplayName;
		if (displayName == null)
		{
			// Never successfully resolved the local player's name this session (e.g. a
			// sync fired before the very first GameTick) — nothing to send yet.
			return;
		}

		showSyncDisclosureOnce();

		AuraSession session = tracker.getSession();
		String deviceId = session.getOrCreateDeviceId();
		long eligibleSeconds = session.getEligibleAuraDurationSeconds();

		if (eligibleSeconds == 0)
		{
			session.recordZeroAuraSync();
			maybeShowZeroAuraNotice(session);
		}

		apiClient.syncAsync(deviceId, displayName, eligibleSeconds, loadedAccountHash);
		executor.execute(this::persist);
	}

	/**
	 * Chat nudge for players who keep syncing but have never earned any Aura — fires
	 * at most once per plugin session (see {@link #zeroAuraNoticeShownThisSession}),
	 * same cadence DropTracker's own {@code loginWarningsShown} uses for its login
	 * warnings. The first time ever still waits for a real streak of unproductive
	 * syncs (see {@link #ZERO_AURA_NOTICE_THRESHOLD}'s doc), so a fresh install is
	 * never nagged in its very first minutes; every later session — once that's been
	 * proven — nudges again immediately on the first zero-Aura sync, without waiting
	 * through the streak a second time.
	 * <p>
	 * Deliberately chat-only wording duplicated from {@link AuraPanel}'s own
	 * always-visible (while at zero) notice rather than one triggering the other — the
	 * panel reflects live state on every refresh, while this fires at most once per
	 * session, so tying them together would either spam the panel's redraw path or
	 * make this method's once-per-session nature depend on Swing repaint timing.
	 */
	private void maybeShowZeroAuraNotice(AuraSession session)
	{
		if (zeroAuraNoticeShownThisSession)
		{
			return;
		}

		boolean thresholdAlreadyCleared = "true".equals(configManager.getConfiguration("aurafarming", ZERO_AURA_THRESHOLD_CLEARED_KEY));
		if (!shouldShowZeroAuraNotice(thresholdAlreadyCleared, session.getZeroAuraSyncStreak(), ZERO_AURA_NOTICE_THRESHOLD))
		{
			return;
		}

		if (!thresholdAlreadyCleared)
		{
			configManager.setConfiguration("aurafarming", ZERO_AURA_THRESHOLD_CLEARED_KEY, true);
		}

		zeroAuraNoticeShownThisSession = true;
		clientThread.invoke(() -> client.addChatMessage(ChatMessageType.CONSOLE, "",
			"Aura Tracker: you haven't earned any Aura yet - still 0 on the leaderboard. Stand still at the Grand Exchange to start earning.", null));
	}

	/**
	 * Pure decision logic pulled out of {@link #maybeShowZeroAuraNotice(AuraSession)}
	 * specifically so it's testable without mocking {@code Client}/{@code
	 * ConfigManager}/{@code ClientThread} — same reasoning as why
	 * {@link AuraSessionTracker}'s state machine takes a plain {@code WorldPoint}
	 * instead of touching {@code Client} itself. Callers have already ruled out
	 * "already shown this session" before calling this — that part is deliberately
	 * left out here since it depends on this plugin instance's own field, not on any
	 * of these three inputs.
	 */
	static boolean shouldShowZeroAuraNotice(boolean thresholdAlreadyCleared, int zeroAuraSyncStreak, int threshold)
	{
		return thresholdAlreadyCleared || zeroAuraSyncStreak >= threshold;
	}

	/**
	 * Opens the community leaderboard in the player's default browser — the panel's
	 * "Open Leaderboard" button is the only trigger. Otherwise, the link only ever
	 * appears once, in the one-time sync disclosure chat message, which is easy to
	 * miss entirely.
	 */
	private void openLeaderboard()
	{
		LinkBrowser.browse(LEADERBOARD_URL);
	}

	private void openDiscord()
	{
		LinkBrowser.browse(DISCORD_URL);
	}

	/**
	 * Exports and uploads the player's current 3D model (equipment, colors, textures)
	 * for the profile page's model viewer — see {@link GlbExporter}. The only trigger is
	 * the panel's "Update 3D Model" button — deliberately never automatic, so exporting
	 * the character's appearance is always a decision the player actively makes. Runs
	 * entirely on the client thread via {@link ClientThread}, so
	 * {@code getLocalPlayer()}/{@code getModel()} are always safe to read fresh here.
	 */
	private void updateModelAsync()
	{
		if (!config.onlineSyncEnabled())
		{
			clientThread.invoke(() -> client.addChatMessage(ChatMessageType.CONSOLE, "",
				"Aura Tracker: enable online sync first (Config → Aura Tracker).", null));
			return;
		}

		clientThread.invoke(() ->
		{
			if (tracker == null)
			{
				return;
			}

			Player localPlayer = client.getLocalPlayer();
			Model model = localPlayer != null ? localPlayer.getModel() : null;
			if (model == null)
			{
				client.addChatMessage(ChatMessageType.CONSOLE, "",
					"Aura Tracker: couldn't read your character right now, try again.", null);
				return;
			}

			byte[] glb;
			try
			{
				glb = GlbExporter.toBytes(client, model, "player", gson);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Aura Tracker: failed to export player model", e);
				client.addChatMessage(ChatMessageType.CONSOLE, "",
					"Aura Tracker: failed to export your 3D model.", null);
				return;
			}

			String deviceId = tracker.getSession().getOrCreateDeviceId();
			client.addChatMessage(ChatMessageType.CONSOLE, "", "Aura Tracker: updating your 3D model...", null);
			apiClient.syncModelAsync(deviceId, glb);
		});
	}

	/**
	 * Satisfies Plugin Hub rule 1.3's disclosure requirement with a one-time, unobtrusive
	 * chat message instead of a blocking confirmation dialog — sync is opt-out, so this
	 * informs rather than asks. {@code ChatMessageType.CONSOLE} matches how other plugins
	 * post non-intrusive system messages. Only ever shown once per install: the flag is
	 * never cleared by toggling sync off and back on.
	 */
	private void showSyncDisclosureOnce()
	{
		if ("true".equals(configManager.getConfiguration("aurafarming", DISCLOSURE_SHOWN_KEY)))
		{
			return;
		}
		configManager.setConfiguration("aurafarming", DISCLOSURE_SHOWN_KEY, true);

		String message = "Aura Tracker: your progress is being sent to an unofficial "
			+ "community server - check your ranking at " + LEADERBOARD_URL
			+ ". To turn this off, see the plugin's settings.";

		// addChatMessage requires the client thread; doSyncOnline() runs on either the
		// background executor or the client thread depending on the caller (see its own
		// javadoc), so this can't assume it's already there.
		clientThread.invoke(() -> client.addChatMessage(ChatMessageType.CONSOLE, "", message, null));
	}

	/**
	 * Swaps in the right account's session whenever the logged-in account differs from
	 * whichever one {@link #tracker} currently holds — a genuine account switch, not
	 * just a relog to the same one (that's the common case and must NOT reset the
	 * in-memory session, matching this class's behavior before per-account scoping
	 * existed). {@code accountHash} ({@link Client#getAccountHash()}), not display name:
	 * survives a character rename, unlike the display-name-keyed screenshot folders
	 * RuneLite's own screenshot plugin uses — see LocalAuraRepository's own doc for the
	 * full reasoning. A no-op while not logged in ({@code getAccountHash() == -1}).
	 */
	private void loadSessionForCurrentAccount()
	{
		long accountHash = client.getAccountHash();
		if (accountHash == -1 || accountHash == loadedAccountHash)
		{
			return;
		}

		// Flush the outgoing account's progress before switching away from it — its own
		// LOGIN_SCREEN/logout transition already does this in the common case, but a
		// direct account-switch-without-restart shouldn't rely on that having happened.
		if (loadedAccountHash != -1)
		{
			repository.save(loadedAccountHash, tracker.getSession());
		}

		AuraSession session = repository.load(accountHash);
		session.resetSession();
		tracker.setSession(session);
		loadedAccountHash = accountHash;
	}

	private void refreshPanel()
	{
		if (tracker == null || panel == null)
		{
			return;
		}

		panel.update(tracker.getSession(), tracker.getState());
	}

	private void persist()
	{
		// No account has been seen yet (plugin enabled before login, or between
		// LOGIN_SCREEN and the next LOGGED_IN) — nothing meaningful to persist. Reads
		// the cached field rather than calling client.getAccountHash() itself so this
		// stays safe to call from the autosave executor thread, same reasoning as
		// lastKnownDisplayName above.
		if (tracker == null || loadedAccountHash == -1)
		{
			return;
		}

		repository.save(loadedAccountHash, tracker.getSession());
	}
}

package com.aurafarming;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Loads and saves {@link AuraSession} data as local JSON files under the RuneLite
 * directory, one file per RuneScape account. This is the ONLY form of persistence in the
 * Phase A (local-only) scope of the project — there is no network client, no remote
 * sync, and no code path in this class that ever opens a socket or makes an HTTP
 * request.
 * <p>
 * Scoped by {@code accountHash} ({@link net.runelite.api.Client#getAccountHash()}),
 * not display name — the same choice RuneLite's own {@code ConfigManager} makes for
 * per-account state, and unlike the display-name-keyed screenshot folders, it survives a
 * character rename. Two different RuneScape accounts played on the same machine
 * therefore never share progress, and a single account keeps its progress across a
 * rename. {@code accountHash} is never sent anywhere by this class — see
 * {@link AuraSession#getOrCreateDeviceId()} for the opaque identifier actually used if
 * online sync is enabled.
 */
@Slf4j
public class LocalAuraRepository
{
	private static final String DIRECTORY_NAME = "aura-tracker";
	private static final String SESSIONS_SUBDIRECTORY = "sessions";

	/**
	 * Sanity ceiling for a hand-edited or corrupted local file — not anti-cheat (a
	 * moderately-sized fabricated edit sails straight through this, same as it always
	 * could), just data hygiene against obviously-absurd values. The real protection
	 * against a tampered file being used to seed the online leaderboard lives
	 * server-side (see aura-web's {@code applySync}: a brand-new device always starts
	 * at 0 there, regardless of what this file claims).
	 */
	private static final long MAX_PLAUSIBLE_ELIGIBLE_SECONDS = 100L * 365 * 24 * 60 * 60;

	private final Gson gson;
	private final File sessionsDir;

	@Inject
	public LocalAuraRepository(Gson gson)
	{
		this(gson, new File(new File(RuneLite.RUNELITE_DIR, DIRECTORY_NAME), SESSIONS_SUBDIRECTORY));
	}

	/**
	 * Package-private constructor allowing tests to point at a temporary directory
	 * instead of the real RuneLite directory.
	 */
	LocalAuraRepository(Gson gson, File sessionsDir)
	{
		this.gson = gson;
		this.sessionsDir = sessionsDir;
		if (!sessionsDir.exists())
		{
			sessionsDir.mkdirs();
		}
	}

	/**
	 * Loads the persisted session for this account, or returns a fresh, zeroed
	 * {@link AuraSession} if no file exists yet for it, or if the file is missing,
	 * corrupt, or contains invalid data. Never throws — a bad local file should never
	 * prevent the plugin from starting.
	 */
	public AuraSession load(long accountHash)
	{
		File file = fileFor(accountHash);
		if (!file.exists())
		{
			return new AuraSession();
		}

		try (Reader reader = new FileReader(file))
		{
			AuraSession loaded = gson.fromJson(reader, AuraSession.class);
			return sanitize(loaded);
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Aura Tracker: failed to load local session file, starting fresh", e);
			return new AuraSession();
		}
	}

	/**
	 * Persists the given session to this account's file, overwriting any previous
	 * version. Failures are logged, never thrown — a failed save should never crash the
	 * client or interrupt gameplay.
	 */
	public void save(long accountHash, AuraSession session)
	{
		session.setLastSavedAtEpochMillis(System.currentTimeMillis());

		try (Writer writer = new FileWriter(fileFor(accountHash)))
		{
			gson.toJson(session, writer);
		}
		catch (IOException e)
		{
			log.warn("Aura Tracker: failed to save local session file", e);
		}
	}

	private File fileFor(long accountHash)
	{
		return new File(sessionsDir, accountHash + ".json");
	}

	/**
	 * Defends against a hand-edited or corrupted file producing an invalid session
	 * (e.g. negative durations), rather than trusting the file's contents blindly.
	 */
	private AuraSession sanitize(AuraSession loaded)
	{
		if (loaded == null
			|| loaded.getEligibleAuraDurationSeconds() < 0
			|| loaded.getEligibleAuraDurationSeconds() > MAX_PLAUSIBLE_ELIGIBLE_SECONDS)
		{
			return new AuraSession();
		}

		return loaded;
	}
}

package com.aurafarming;

import java.util.concurrent.TimeUnit;

/**
 * Measures elapsed time between successive calls using a monotonic clock, with
 * protections against lag spikes, client freezes, and clock manipulation.
 * <p>
 * Deliberately uses {@link System#nanoTime()} rather than {@link System#currentTimeMillis()}:
 * {@code nanoTime} is monotonic and immune to system clock changes (NTP adjustments,
 * manual clock changes, daylight saving), while {@code currentTimeMillis} is not.
 * {@code GameTick} counting ("1 point per tick") is deliberately avoided because tick
 * duration is nominally ~600ms but varies under server lag or client hitches, which
 * would cause drift and incorrect scoring.
 * <p>
 * Returns nanoseconds rather than seconds: a game tick is ~600ms, so truncating every
 * call to whole seconds would silently discard almost all elapsed time. Callers are
 * expected to accumulate the returned nanoseconds and only convert to whole seconds once
 * enough has built up (see {@link AuraSessionTracker}), carrying any remainder forward.
 */
public class AuraTimingClock
{
	/**
	 * Maximum delta counted from a single measurement, in nanoseconds (~2 game ticks).
	 * Caps the impact of an occasional lag spike so a brief stall can't be counted as if
	 * the player had been idle the whole time.
	 */
	static final long MAX_DELTA_NANOS = TimeUnit.MILLISECONDS.toNanos(1200);

	/**
	 * Above this threshold, the delta is assumed to be a freeze, a long lag spike, or the
	 * client having been minimized/suspended for a long time, and is discarded entirely
	 * rather than counted — the player should not "wake up" with a large amount of Aura
	 * for having done nothing while the client was frozen.
	 */
	static final long FREEZE_THRESHOLD_NANOS = TimeUnit.SECONDS.toNanos(30);

	private final NanoClock nanoClock;
	private long lastNanos;
	private boolean started;

	public AuraTimingClock()
	{
		this(System::nanoTime);
	}

	/**
	 * Package-private constructor allowing tests to inject a fake clock.
	 */
	AuraTimingClock(NanoClock nanoClock)
	{
		this.nanoClock = nanoClock;
	}

	/**
	 * Marks the current instant as the new reference point, without returning an elapsed
	 * duration. Call this whenever accumulation should NOT include the time since the
	 * last checkpoint (e.g. transitioning into EARNING_AURA for the first time, or
	 * resuming after a pause).
	 */
	public void reset()
	{
		lastNanos = nanoClock.nanoTime();
		started = true;
	}

	/**
	 * Returns the capped, non-negative elapsed duration in nanoseconds since the last
	 * call to {@link #reset()} or {@link #elapsedNanosAndReset()}, and resets the
	 * reference point to now.
	 * <p>
	 * If this is the first call since construction (no prior {@link #reset()}), returns 0
	 * and simply establishes the reference point — this avoids ever counting time that
	 * elapsed before tracking meaningfully started.
	 */
	public long elapsedNanosAndReset()
	{
		long now = nanoClock.nanoTime();

		if (!started)
		{
			lastNanos = now;
			started = true;
			return 0L;
		}

		long deltaNanos = now - lastNanos;
		lastNanos = now;

		if (deltaNanos <= 0)
		{
			// Impossible under a monotonic clock in practice, but never allow a negative
			// or zero delta to produce anything but zero.
			return 0L;
		}

		if (deltaNanos > FREEZE_THRESHOLD_NANOS)
		{
			// Likely a freeze, long minimize, or suspend/resume. Discard rather than count.
			return 0L;
		}

		return Math.min(deltaNanos, MAX_DELTA_NANOS);
	}

	/**
	 * Thin seam over {@link System#nanoTime()} so tests can control the clock without
	 * sleeping real time.
	 */
	@FunctionalInterface
	interface NanoClock
	{
		long nanoTime();
	}
}

package com.aurafarming;

/**
 * Converts eligible duration into an Aura score.
 * <p>
 * This is the ONLY place the Aura formula is allowed to live. Nothing else in the
 * plugin — tracker, panel, or repository — should hardcode the conversion. This keeps
 * the formula changeable later without touching tracking or persistence logic.
 * <p>
 * MVP formula: 1 Aura point per minute of eligible time, rounded down.
 */
public class AuraScoreCalculator
{
	private static final long SECONDS_PER_AURA_POINT = 60L;

	/**
	 * @param eligibleSeconds total eligible seconds standing still in the Grand Exchange.
	 *                        Must be non-negative; negative input is treated as zero.
	 * @return the Aura score, rounded down to whole points.
	 */
	public long toAuraPoints(long eligibleSeconds)
	{
		if (eligibleSeconds <= 0)
		{
			return 0L;
		}

		return eligibleSeconds / SECONDS_PER_AURA_POINT;
	}
}

