package com.aurafarming;

import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;

/**
 * Owns the Aura tracking state machine. This is the only class in the plugin that
 * decides whether Aura is currently accumulating; everything else (panel, overlay,
 * repository) only reads from it.
 * <p>
 * Only ever consulted with the LOCAL player's own {@link WorldPoint} and the client's
 * own {@link GameState}. No other player's position, appearance, or actions are ever
 * read by this class, and none should ever be passed into it.
 */
public class AuraSessionTracker
{
	private final GrandExchangeArea grandExchangeArea;
	private final AuraTimingClock earningClock;
	private final LongSupplier nanoTimeSupplier;

	private AuraSession session;
	private AuraState state = AuraState.LOGGED_OUT;
	private WorldPoint anchorTile;
	private long idleStartNanos;

	/**
	 * Nanoseconds of eligible time accumulated but not yet converted into a whole
	 * second. A game tick is ~600ms, so without this carry-over, truncating every tick
	 * to whole seconds would silently discard almost all eligible time.
	 */
	private long carryNanos;

	public AuraSessionTracker(GrandExchangeArea grandExchangeArea, AuraTimingClock earningClock, AuraSession session)
	{
		this(grandExchangeArea, earningClock, session, System::nanoTime);
	}

	/**
	 * Package-private constructor allowing tests to inject a fake clock, so state
	 * machine tests never depend on real wall-clock sleeps.
	 */
	AuraSessionTracker(GrandExchangeArea grandExchangeArea, AuraTimingClock earningClock, AuraSession session,
						LongSupplier nanoTimeSupplier)
	{
		this.grandExchangeArea = grandExchangeArea;
		this.earningClock = earningClock;
		this.session = session;
		this.nanoTimeSupplier = nanoTimeSupplier;
	}

	public AuraState getState()
	{
		return state;
	}

	public AuraSession getSession()
	{
		return session;
	}

	/**
	 * Replaces the tracked session, e.g. after loading persisted data at startup.
	 * Does not touch the current state machine state.
	 */
	public void setSession(AuraSession session)
	{
		this.session = session;
	}

	/**
	 * Must be called once per {@code GameTick} with the local player's own world
	 * location. Pass {@code null} if the local player is not currently resolvable
	 * (e.g. mid-loading) — this is treated the same as being outside the Grand Exchange.
	 *
	 * @param localPlayerLocation the local player's own {@code WorldPoint}, or null.
	 * @param idleDelaySeconds    seconds a player must stand still before Aura starts
	 *                            accumulating (from {@code AuraConfig}).
	 */
	public void onGameTick(WorldPoint localPlayerLocation, int idleDelaySeconds)
	{
		if (state == AuraState.LOGGED_OUT)
		{
			return;
		}

		boolean inGrandExchange = localPlayerLocation != null && grandExchangeArea.contains(localPlayerLocation);

		if (!inGrandExchange)
		{
			if (state != AuraState.IN_GAME)
			{
				state = AuraState.IN_GAME;
				anchorTile = null;
			}
			return;
		}

		// Player is inside the Grand Exchange this tick.
		if (state == AuraState.IN_GAME || state == AuraState.PAUSED)
		{
			state = AuraState.IN_GE;
		}

		if (state == AuraState.IN_GE)
		{
			// (Re-)establish the anchor tile and begin the idle wait immediately — this
			// state is transitional and does not persist across ticks by design.
			anchorTile = localPlayerLocation;
			idleStartNanos = nanoTimeSupplier.getAsLong();
			state = AuraState.WAITING_FOR_IDLE;
			return;
		}

		// state is WAITING_FOR_IDLE or EARNING_AURA from here.
		if (!localPlayerLocation.equals(anchorTile))
		{
			// Moved tiles: reset the idle wait, whether we were waiting or already earning.
			anchorTile = localPlayerLocation;
			idleStartNanos = nanoTimeSupplier.getAsLong();
			state = AuraState.WAITING_FOR_IDLE;
			return;
		}

		if (state == AuraState.WAITING_FOR_IDLE)
		{
			long idleElapsedNanos = nanoTimeSupplier.getAsLong() - idleStartNanos;
			long idleDelayNanos = TimeUnit.SECONDS.toNanos(Math.max(0, idleDelaySeconds));
			if (idleElapsedNanos >= idleDelayNanos)
			{
				state = AuraState.EARNING_AURA;
				// Start counting from this instant, not from when the tile was first reached.
				earningClock.reset();
			}
			return;
		}

		// state == EARNING_AURA, still on the anchor tile: accumulate.
		long deltaNanos = earningClock.elapsedNanosAndReset();
		carryNanos += deltaNanos;

		long wholeSeconds = carryNanos / 1_000_000_000L;
		if (wholeSeconds > 0)
		{
			session.addEligibleSeconds(wholeSeconds);
			carryNanos -= wholeSeconds * 1_000_000_000L;
		}
	}

	/**
	 * Must be called whenever the client's {@link GameState} changes. Handles login,
	 * logout, world hops, loading screens, and connection loss by pausing or resetting
	 * tracking as appropriate — never by inferring anything from other players or
	 * from input devices.
	 */
	public void onGameStateChanged(GameState newState)
	{
		switch (newState)
		{
			case LOGIN_SCREEN:
			case LOGIN_SCREEN_AUTHENTICATOR:
			case CONNECTION_LOST:
				state = AuraState.LOGGED_OUT;
				anchorTile = null;
				carryNanos = 0;
				break;
			case HOPPING:
			case LOADING:
			case LOGGING_IN:
				if (state != AuraState.LOGGED_OUT)
				{
					state = AuraState.PAUSED;
					anchorTile = null;
				}
				break;
			case LOGGED_IN:
				if (state == AuraState.LOGGED_OUT)
				{
					state = AuraState.IN_GAME;
				}
				else if (state == AuraState.PAUSED)
				{
					state = AuraState.IN_GAME;
				}
				// The next onGameTick call re-establishes GE membership and, if
				// applicable, the idle wait from scratch — nothing is assumed here.
				break;
			default:
				// Unknown/unused states are ignored rather than guessed at.
				break;
		}
	}
}

package com.aurafarming;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Read-only sidebar panel. Only ever reads from {@link AuraSessionTracker} and
 * {@link AuraScoreCalculator} — it never mutates tracking state itself.
 * <p>
 * Stats are boxed "cards" (own background, border, padding) rather than bare labels
 * sitting directly on the panel background — modeled after how core RuneLite panels
 * like {@code XpPanel} separate content from the base panel visually, instead of
 * everything blending into one flat gray field.
 * <p>
 * The outer layout is {@link BorderLayout} with content anchored at
 * {@link BorderLayout#NORTH}, not a bare top-level {@link BoxLayout} — the same trick
 * {@code XpPanel} uses so the stat cards keep their natural height instead of stretching
 * to fill leftover vertical space.
 * <p>
 * All text stays at {@link FontManager}'s native size (16px) — checked directly against
 * {@code XpPanel}/{@code XpInfoBox}/{@code PartyStatusOverlay}/{@code DevToolsOverlay} in
 * RuneLite core: none of them ever call {@code deriveFont} with a size above 16. An
 * earlier version of this panel scaled the headline Aura number up to 22-26px, which
 * rendered as illegible blocky glyphs — not a one-off font bug, but this codebase's fonts
 * simply not being designed to scale past their native size. Emphasis here comes from
 * color and bold weight only, the same way {@code XpInfoBox#htmlLabel} highlights numbers
 * within otherwise plain-sized text.
 */
public class AuraPanel extends PluginPanel
{
	private static final Color CARD_BORDER_COLOR = ColorScheme.DARK_GRAY_HOVER_COLOR;

	private final AuraScoreCalculator scoreCalculator;

	private final JLabel auraValueLabel = new JLabel();
	private final JLabel totalTimeValueLabel = new JLabel();
	private final JLabel sessionTimeValueLabel = new JLabel();
	private final JLabel stateValueLabel = new JLabel();

	/**
	 * Ambient reminder, visible only while the all-time total is still zero — never a
	 * one-off popup. Disappears for good the moment the player earns any Aura at all
	 * (there's no path back to zero, so no logic ever needs to re-show it). Distinct
	 * from {@code AuraPlugin}'s one-time chat nudge: that one waits for a streak of
	 * unproductive syncs before firing once; this one reflects live state on every
	 * {@link #update} call, with no delay and no memory of whether it's been "shown"
	 * before.
	 */
	private final JPanel zeroAuraNotice = buildZeroAuraNotice();

	/**
	 * Every card built by {@link #statCard}, kept around so the constructor can freeze
	 * their height <em>after</em> the first real {@link #update} call rather than inside
	 * {@code statCard} itself. Measuring height any earlier was the actual bug behind a
	 * string of "text looks bottom-aligned" reports: at construction time the value
	 * labels are still empty (text arrives later via {@code update}), and this look and
	 * feel (RuneLite's FlatLaf-based {@code RuneLiteLAF}) reports a shorter preferred
	 * height for an empty label than for one with real text. Freezing height from that
	 * too-short empty-state measurement left every card a few pixels short of what the
	 * real text needed, and since children stack top-down, the shortfall always ate into
	 * the bottom margin first — confirmed by literally rendering the panel to a PNG and
	 * measuring pixel rows (top gap 13px, bottom gap 1px) rather than guessing again.
	 */
	private final List<JPanel> statCards = new ArrayList<>();

	/**
	 * @param onOpenLeaderboardClicked invoked when the user clicks "Open Leaderboard" —
	 *                                 most players never see the leaderboard link
	 *                                 otherwise, since it only ever appears once, in the
	 *                                 one-time sync disclosure chat message.
	 * @param onUpdateModelClicked invoked when the user clicks the "Update 3D Model"
	 *                             button — a deliberate, user-initiated action (same UX
	 *                             as RuneProfile's own "Update Player Model" button),
	 *                             never triggered automatically. The panel only relays
	 *                             the click; it has no opinion on what happens after,
	 *                             keeping it purely presentational like the rest of this
	 *                             class.
	 */
	public AuraPanel(AuraScoreCalculator scoreCalculator, Runnable onOpenLeaderboardClicked, Runnable onOpenDiscordClicked, Runnable onUpdateModelClicked)
	{
		super(false);
		this.scoreCalculator = scoreCalculator;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(new EmptyBorder(10, 10, 10, 10));

		content.add(buildTitle());
		content.add(Box.createRigidArea(new Dimension(0, 18)));
		content.add(addCard(statCard("AURA", auraValueLabel, true)));
		content.add(verticalGap());
		content.add(addCard(statCard("TIME AT THE GE", totalTimeValueLabel, false)));
		content.add(verticalGap());
		content.add(addCard(statCard("CURRENT SESSION", sessionTimeValueLabel, false)));
		content.add(verticalGap());
		content.add(addCard(statCard("STATUS", stateValueLabel, false)));
		content.add(Box.createRigidArea(new Dimension(0, 18)));
		content.add(zeroAuraNotice);
		content.add(buildButton("Open Leaderboard", onOpenLeaderboardClicked));
		content.add(verticalGap());
		content.add(buildButton("Join Discord Community", onOpenDiscordClicked));
		content.add(verticalGap());
		content.add(buildButton("Update 3D Model", onUpdateModelClicked));

		add(content, BorderLayout.NORTH);

		update(new AuraSession(), AuraState.LOGGED_OUT);

		// Only now do the value labels hold real text ("0", "0m", "Offline") — freeze
		// each card's height off of *this* preferred size, not the empty-label one from
		// construction. See the statCards field doc for why this ordering matters.
		for (JPanel card : statCards)
		{
			card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		}
	}

	private JPanel addCard(JPanel card)
	{
		statCards.add(card);
		return card;
	}

	private static Component verticalGap()
	{
		return Box.createRigidArea(new Dimension(0, 12));
	}

	private static JLabel buildTitle()
	{
		// Left-aligned, not centered — everything below it (cards, button) is
		// left-aligned too, and a centered title against left-aligned content read as
		// inconsistent/misaligned. One shared left margin for the whole panel instead.
		JLabel title = new JLabel("AURA TRACKER");
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(16f));
		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setHorizontalAlignment(SwingConstants.LEFT);
		title.setAlignmentX(LEFT_ALIGNMENT);
		return title;
	}

	/**
	 * @param emphasized the Aura card gets the brand color and the bold weight — it's the
	 *                   headline number, everything else is supporting detail. Same point
	 *                   size as every other value, matching the rest of this codebase's
	 *                   fonts (see the class doc for why).
	 */
	private static JPanel statCard(String label, JLabel valueLabel, boolean emphasized)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new CompoundBorder(
			new LineBorder(CARD_BORDER_COLOR, 1, true),
			new EmptyBorder(12, 16, 12, 16)));
		card.setAlignmentX(LEFT_ALIGNMENT);

		JLabel labelText = new JLabel(label);
		labelText.setFont(FontManager.getRunescapeSmallFont());
		labelText.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		labelText.setHorizontalAlignment(SwingConstants.LEFT);
		labelText.setAlignmentX(LEFT_ALIGNMENT);

		valueLabel.setForeground(emphasized ? ColorScheme.BRAND_ORANGE : Color.WHITE);
		valueLabel.setFont(emphasized ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeFont());
		valueLabel.setHorizontalAlignment(SwingConstants.LEFT);
		valueLabel.setAlignmentX(LEFT_ALIGNMENT);

		// Glue above and below the label+value pair, not just insets, so the pair is
		// forced to sit at the card's true vertical center regardless of how tall the
		// card ends up being — insets alone assume the label/value block's own preferred
		// height already accounts for all the vertical space the card allocates, which
		// isn't reliable with this pixel font's own inflated internal line metrics.
		card.add(Box.createVerticalGlue());
		card.add(labelText);
		card.add(Box.createRigidArea(new Dimension(0, 6)));
		card.add(valueLabel);
		card.add(Box.createVerticalGlue());

		// Max height is frozen later, in the constructor, once every value label holds
		// its real text — not here. See the statCards field doc for why. (Max width is
		// still left unbounded here on purpose: that's what lets the constructor's later
		// setMaximumSize call — width MAX_VALUE, height pinned — stretch the card to the
		// panel's full width instead of shrinking to its own content width, the standard
		// BoxLayout "fill" workaround.)

		return card;
	}

	/**
	 * Bottom margin (18px) is baked into this panel's own border rather than added as
	 * a separate {@code Box.createRigidArea} after it, so hiding it via
	 * {@code setVisible(false)} in {@link #update} removes its trailing gap too —
	 * {@link BoxLayout} skips invisible children entirely, so no leftover empty space
	 * is left between the STATUS card and the buttons below when the player already
	 * has Aura.
	 */
	private static JPanel buildZeroAuraNotice()
	{
		JPanel notice = new JPanel();
		notice.setLayout(new BoxLayout(notice, BoxLayout.Y_AXIS));
		notice.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		notice.setBorder(new CompoundBorder(
			new MatteBorder(0, 3, 0, 0, ColorScheme.BRAND_ORANGE),
			new EmptyBorder(8, 10, 18, 10)));
		notice.setAlignmentX(LEFT_ALIGNMENT);

		JLabel text = new JLabel("<html>You haven't earned any Aura yet &mdash; still 0 on the leaderboard.</html>");
		text.setFont(FontManager.getRunescapeSmallFont());
		text.setForeground(ColorScheme.BRAND_ORANGE);
		text.setAlignmentX(LEFT_ALIGNMENT);

		notice.add(text);
		// The label's text never changes post-construction (unlike the stat cards'
		// value labels), so its preferred size is already final here — no need to
		// defer freezing the height until after a real update() call the way
		// statCard's height-freezing loop in the constructor has to.
		notice.setMaximumSize(new Dimension(Integer.MAX_VALUE, notice.getPreferredSize().height));
		return notice;
	}

	private static JButton buildButton(String label, Runnable onClick)
	{
		JButton button = new JButton(label);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setForeground(Color.WHITE);
		button.setAlignmentX(LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, button.getPreferredSize().height + 8));
		button.addActionListener(e -> onClick.run());
		return button;
	}

	/**
	 * Refreshes the displayed values. Intended to be called on a fixed-rate timer
	 * (e.g. once per second), never once per {@code GameTick} — the panel does not need
	 * tick-level precision and redrawing on every tick would be wasted work.
	 */
	public void update(AuraSession session, AuraState state)
	{
		long totalEligibleSeconds = session.getEligibleAuraDurationSeconds();

		long auraPoints = scoreCalculator.toAuraPoints(totalEligibleSeconds);
		auraValueLabel.setText(formatNumber(auraPoints));

		totalTimeValueLabel.setText(formatDuration(totalEligibleSeconds));

		sessionTimeValueLabel.setText(formatDuration(session.getCurrentSessionEligibleSeconds()));

		stateValueLabel.setText(describeState(state));

		boolean showZeroAuraNotice = totalEligibleSeconds == 0;
		if (zeroAuraNotice.isVisible() != showZeroAuraNotice)
		{
			zeroAuraNotice.setVisible(showZeroAuraNotice);
			revalidate();
			repaint();
		}
	}

	private static String describeState(AuraState state)
	{
		switch (state)
		{
			case EARNING_AURA:
				return "Farming Aura";
			case WAITING_FOR_IDLE:
				return "Waiting for you to stop";
			case IN_GE:
			case IN_GAME:
				return "Walk to the GE to start";
			case PAUSED:
				return "Paused";
			case LOGGED_OUT:
			default:
				return "Offline";
		}
	}

	private static String formatNumber(long value)
	{
		return String.format(Locale.US, "%,d", value);
	}

	private static String formatDuration(long totalSeconds)
	{
		if (totalSeconds < 0)
		{
			totalSeconds = 0;
		}

		long days = totalSeconds / 86400;
		long hours = (totalSeconds % 86400) / 3600;
		long minutes = (totalSeconds % 3600) / 60;

		if (days > 0)
		{
			return String.format("%dd %02dh %02dm", days, hours, minutes);
		}
		if (hours > 0)
		{
			return String.format("%dh %02dm", hours, minutes);
		}
		return String.format("%dm", minutes);
	}
}
